additionalExercises.referenceSolution:
#include <iostream>
#include <print>
#include <string>
#include <vector>

class Board {
public:
    Board(int rows, int cols) : rows_(rows), cols_(cols), cells_(static_cast<std::size_t>(rows * cols)) {}

    auto &at(this auto &self, int row, int col) {
        return self.cells_[static_cast<std::size_t>(row * self.cols_ + col)];
    }

    int rows() const {
        return rows_;
    }

    int cols() const {
        return cols_;
    }

private:
    int rows_;
    int cols_;
    std::vector<long long> cells_;
};

long long row_sum(const Board &b, int i) {
    long long s = 0;
    for (int j = 0; j < b.cols(); j++) {
        s += b.at(i, j);
    }
    return s;
}

long long col_sum(const Board &b, int j) {
    long long s = 0;
    for (int i = 0; i < b.rows(); i++) {
        s += b.at(i, j);
    }
    return s;
}

int main() {
    int r, c;
    std::cin >> r >> c;
    Board board(r, c);
    std::string command;
    while (std::cin >> command) {
        if (command == "put") {
            int i, j;
            long long v;
            std::cin >> i >> j >> v;
            board.at(i, j) = v;
        } else if (command == "row") {
            int i;
            std::cin >> i;
            std::println("{}", row_sum(board, i));
        } else {
            int j;
            std::cin >> j;
            std::println("{}", col_sum(board, j));
        }
    }
    return 0;
}

