int main() {
    // Напишите решение здесь.
    return 0;
}

additionalExercises.referenceSolution:
#include <iostream>
#include <print>
#include <string>
#include <vector>

class Account {
public:
    explicit Account(long long balance) : balance_(balance) {}

    bool transfer(Account &to, long long amount) {
        long long fee = amount / 100;
        if (this == &to || amount <= 0 || amount + fee > balance_) {
            return false;
        }
        balance_ -= amount + fee;
        to.balance_ += amount;
        return true;
    }

    long long balance() const {
        return balance_;
    }

private:
    long long balance_;
};

int main() {
    int n;
    std::cin >> n;
    std::vector<Account> accounts;
    for (int i = 0; i < n; i++) {
        long long b;
        std::cin >> b;
        accounts.emplace_back(b);
    }
    std::string command;
    while (std::cin >> command) {
        if (command == "show") {
            std::string line;
            for (const Account &a : accounts) {
                line += (line.empty() ? "" : " ") + std::to_string(a.balance());
            }
            std::println("{}", line);
            continue;
        }
        int i, j;
        long long amount;
        std::cin >> i >> j >> amount;
        if (i < 0 || j < 0 || i >= n || j >= n) {
            std::println("нет счёта");
        } else if (accounts[static_cast<std::size_t>(i)].transfer(accounts[static_cast<std::size_t>(j)], amount)) {
            std::println("ок");
        } else {
            std::println("отказ");
        }
    }
    return 0;
}

